catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
function fetchAttendee(attendeeId) {
    var ga = new GlideAjax('AttendeeUtils');
    ga.addParam('sysparm_name', 'getAttendeeDetails');
    ga.addParam('sysparm_attendee_id', attendeeId);
    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            alert(data.error);
        } else {
            alert(
                "Name: " + data.first_name + " " + data.last_name +
                "\nEmail: " + data.email +
                "\nContact: " + data.contact_number +
                "\nEvent: " + data.event_id
            );
        }
    });
}

   //Type appropriate comment here, and begin script below

}
